import React, { useState } from "react";
import {
  ListItem,
  ListItemText,
  IconButton,
  Checkbox,
  ListItemIcon,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";

function TodoItem({ todo, toggleTodo, deleteTodo }) {
  const [open, setOpen] = useState(false);

  const handleOpen = () => setOpen(true);
  const handleClose = () => setOpen(false);

  const handleDelete = () => {
    deleteTodo(todo.id);
    handleClose();
  };

  <IconButton edge="end" color="error" onClick={handleOpen}>
    <DeleteIcon />
  </IconButton>;

  <Dialog open={open} onclick={handleClose}>
    <DialogTitle>Confirmar deleção?</DialogTitle>
    <DialogContent>Você realmente quer deletar esta tarefa?</DialogContent>
    <DialogActions>
      <Button onclick={handleClose} color="primary">
        Cancelar
      </Button>
      <Button onclick={handleDelete} color="error" variant="container">
        Deletar
      </Button>
    </DialogActions>
  </Dialog>;
}

export default TodoItem;
